'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const seed={people:[
{id:1,name:'Aarav Sharma',role:'Backend engineer',team:'Engineering',planned:46,available:40,open:8,overdue:2,logged:8,elapsed:8,goal:68},
{id:2,name:'Priya Nair',role:'Frontend engineer',team:'Engineering',planned:34,available:40,open:6,overdue:0,logged:7,elapsed:8,goal:74},
{id:3,name:'Rohan Mehta',role:'QA engineer',team:'Engineering',planned:18,available:32,open:4,overdue:0,logged:null,elapsed:8,goal:61},
{id:4,name:'Ananya Rao',role:'Delivery consultant',team:'Delivery',planned:36,available:32,open:7,overdue:1,logged:8,elapsed:8,goal:56},
{id:5,name:'Kabir Singh',role:'Implementation lead',team:'Delivery',planned:28,available:40,open:5,overdue:0,logged:6,elapsed:8,goal:82},
{id:6,name:'Meera Iyer',role:'Product designer',team:'Engineering',planned:30,available:40,open:5,overdue:0,logged:8,elapsed:8,goal:71}],
alerts:[{id:1,type:'delivery',team:'Engineering',title:'Client API validation is blocked',detail:'Aarav · Staging credentials missing for 2 days · Release due 16 Oct',action:'Review blocker',project:1},
{id:2,type:'delivery',team:'Engineering',title:'Aarav has 6h more work than capacity',detail:'46h planned / 40h available · Review scope or move a suitable task',action:'Balance workload',person:1},
{id:3,type:'delivery',team:'Delivery',title:'Ananya has 4h more work than capacity',detail:'36h planned / 32h available · Approved leave on 15 Oct',action:'Balance workload',person:4},
{id:4,type:'approval',team:'Engineering',title:'Priya’s leave request needs a decision',detail:'16 Oct · 1 day · Approval will reduce weekly capacity from 40h to 32h',action:'Review request',person:2},
{id:5,type:'data',team:'Engineering',title:'Rohan’s effort log is incomplete',detail:'12 Oct · Attendance available: 8h · No effort entry recorded',action:'Review data gap',person:3}],
projects:[{id:1,name:'Brabo platform · API release',team:'Engineering',owner:'Aarav Sharma',done:12,total:18,due:'16 Oct',blocked:true,overdue:2},
{id:2,name:'Client onboarding · Phase 2',team:'Delivery',owner:'Ananya Rao',done:8,total:14,due:'16 Oct',blocked:false,overdue:1},
{id:3,name:'People platform · UX refresh',team:'Engineering',owner:'Meera Iyer',done:9,total:12,due:'20 Oct',blocked:false,overdue:0}],
leaves:[{name:'Rohan Mehta',team:'Engineering',day:'14',backup:'Priya Nair',state:'Approved'}, {name:'Ananya Rao',team:'Delivery',day:'15',backup:'Kabir Singh',state:'Approved'}]};
let state=structuredClone(seed),filter='all',team='all';const inTeam=x=>team==='all'||x.team===team;
function show(title,body){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;if(!$('#dialog').open)$('#dialog').showModal();}
let timer;function toast(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,4000);}
function render(){const people=state.people.filter(inTeam),alerts=state.alerts.filter(inTeam),projects=state.projects.filter(inTeam),over=people.filter(p=>p.planned>p.available),hours=people.reduce((s,p)=>s+p.available,0),planned=people.reduce((s,p)=>s+p.planned,0),late=people.reduce((s,p)=>s+p.overdue,0);
$('#brief-text').textContent=`${projects.filter(p=>p.blocked||p.overdue).length} projects need a delivery review. ${over.length} people are over capacity; ${people.reduce((s,p)=>s+Math.max(0,p.available-p.planned),0)}h is available elsewhere in the team. ${alerts.filter(a=>a.type==='approval').length} leave request awaits a decision.`;
$('#metrics').innerHTML=[['Overdue tasks',late,'Open tasks past their due date','attention','alert'],['Capacity planned',Math.round(planned/hours*100)+'%',`${planned}h planned / ${hours}h available`,'capacity',''],['Over capacity',over.length,`${people.length} direct reports in this view`,'capacity',over.length?'alert':''],['Projects on track',`${projects.filter(p=>!p.blocked&&!p.overdue).length}/${projects.length}`,'No blockers or overdue open tasks','delivery','']].map(m=>`<button class="metric ${m[4]}" data-jump="${m[3]}"><label>${m[0]} ↗</label><strong>${m[1]}</strong><small>${m[2]}</small></button>`).join('');
$('#nav-count').textContent=alerts.length;$('#attention-count').textContent=alerts.length;const visible=alerts.filter(a=>filter==='all'||a.type===filter);$('#attention-list').innerHTML=visible.map(a=>`<div class="item"><span class="item-icon ${a.type}">${a.type==='delivery'?'!':a.type==='approval'?'✓':'◷'}</span><div class="item-body"><h3>${esc(a.title)}</h3><p>${esc(a.detail)}</p><button class="button" data-alert="${a.id}">${a.action} →</button></div></div>`).join('')||'<p class="empty">No items need attention in this view.</p>';
$('#project-count').textContent=projects.length;$('#projects').innerHTML=projects.map(p=>`<div class="project ${p.blocked||p.overdue?'warn':''}" role="button" tabindex="0" data-project="${p.id}"><div class="project-top"><h3>${p.name}</h3><span class="tag ${p.blocked||p.overdue?'warn':''}">${p.blocked?'Blocked':p.overdue?'At risk':'On track'}</span></div><small>${p.owner} · Due ${p.due}</small><div class="progress"><i style="width:${p.done/p.total*100}%"></i></div><div class="project-bottom"><span>${p.done}/${p.total} tasks complete</span><span>${p.overdue?`${p.overdue} overdue`: 'No overdue tasks'}</span></div></div>`).join('');
const term=$('#search').value.toLowerCase();$('#members').innerHTML=people.filter(p=>(p.name+' '+p.role).toLowerCase().includes(term)).map(p=>`<tr><td><div class="person"><span class="avatar">${p.name.split(' ').map(n=>n[0]).join('')}</span><span><b>${p.name}</b><small>${p.role}</small></span></div></td><td><div class="load ${p.planned>p.available?'over':''}"><b>${p.planned}h / ${p.available}h</b><small>${Math.round(p.planned/p.available*100)}%</small><div class="progress"><i style="width:${Math.min(100,p.planned/p.available*100)}%"></i></div></div></td><td>${p.open} open <span class="${p.overdue?'late':'muted'}">· ${p.overdue} overdue</span></td><td>${p.logged===null?'<span class="tag neutral">Missing log</span>':`${p.logged}h / ${p.elapsed}h <small>${Math.round(p.logged/p.elapsed*100)}% recorded</small>`}</td><td>${p.goal}%<small>Quarterly plan</small></td><td><button class="text" data-person="${p.id}">Review →</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No team members match your search.</td></tr>';
$('#goal-list').innerHTML=[['Engineering','Improve release reliability',68,'Target: 95% releases pass acceptance first time · Current: 89%','Needs review'],['Delivery','Shorten client onboarding',56,'Target: ≤10 days median onboarding · Current: 13 days','Needs review']].filter(g=>team==='all'||g[0]===team).map(g=>`<div class="goal"><div class="goal-top"><b>${g[1]}</b><span class="tag warn">${g[4]}</span></div><div class="progress"><i style="width:${g[2]}%"></i></div><p>${g[2]}% of target improvement achieved · ${g[3]}</p></div>`).join('');
$('#leave-list').innerHTML=state.leaves.filter(inTeam).map(l=>`<div class="leave"><div class="date">OCT<b>${l.day}</b></div><div><b>${l.name} <span class="tag">${l.state}</span></b><p>1 day leave · Coverage: ${l.backup}</p></div></div>`).join('')||'<p class="empty">No approved leave in this view.</p>';
}
function person(id){const p=state.people.find(p=>p.id===id);show(p.name,`<p>${p.role} · ${p.team}</p><div class="callout"><b>${p.planned}h planned / ${p.available}h available this week</b><br>${p.planned>p.available?`${p.planned-p.available}h above capacity. Review scope, due dates and skills before reassigning work.`:`${p.available-p.planned}h of unallocated capacity. Confirm availability before assigning work.`}</div><p>${p.open} open tasks · ${p.overdue} overdue · Quarterly plan ${p.goal}% complete.</p><p>Effort recorded through 12 Oct: ${p.logged===null?'not available':p.logged+'h'} against ${p.elapsed}h elapsed capacity. This is data completeness, not a performance score.</p><button class="button" data-balance="${id}">Explore workload adjustment</button>`);}
function balance(id){const p=state.people.find(p=>p.id===id),candidates=state.people.filter(q=>q.id!==id&&q.team===p.team&&q.available-q.planned>=4);show('Review a workload adjustment',`<p>Move a sample 4h task from ${p.name}. This demonstrates capacity calculations; production reassignment needs task-level scope, skills and due dates.</p><div class="callout">Current load: ${p.planned}h / ${p.available}h. After moving 4h: ${p.planned-4}h / ${p.available}h.</div>${candidates.length?`<form id="move-form"><label class="form">Proposed owner<select name="owner">${candidates.map(q=>`<option value="${q.id}">${q.name} · ${q.available-q.planned}h available</option>`).join('')}</select></label><input type="hidden" name="from" value="${id}"><button class="button primary">Apply sample adjustment</button></form>`:'<p>No teammate has 4h available. Discuss scope or dates instead.</p>'}`);}
function project(id){const p=state.projects.find(p=>p.id===id);show(p.name,`<p>Owner: ${p.owner} · Due ${p.due} · ${p.done}/${p.total} tasks complete.</p><div class="callout">${p.blocked?'Release validation is waiting for staging credentials. Dependency owner: client IT.':p.overdue?'Client acceptance checklist is overdue. Confirm a revised commitment with the owner.':'No known blockers or overdue tasks in this sample.'}</div><p>Recommended production drill-down: open tasks, blocker age, dependency owner, next milestone, and status history.</p>${p.blocked?`<button class="button primary" data-unblock="${id}">Mark sample blocker resolved</button>`:''}`);}
function alertDetail(id){const a=state.alerts.find(a=>a.id===id);if(a.type==='delivery')return a.person?balance(a.person):project(a.project);if(a.type==='approval')show('Review leave request',`<p>Priya Nair · Friday, 16 Oct · Full day leave.</p><div class="callout">Approving changes capacity from 40h to 32h. With 34h planned, Priya will be 2h over capacity. Agree coverage or reduce planned work.</div><p>Suggested coverage: Rohan Mehta. Coverage must be confirmed separately.</p><button class="button primary" data-approve="${id}">Approve in sample</button> <button class="button" data-decline="${id}">Decline in sample</button>`);else show('Review missing effort data',`<p>Rohan Mehta · 12 Oct · 8h attendance available; no effort entry recorded.</p><div class="callout">Verify the effort entry or attendance sync before interpreting this gap. Logged hours do not measure delivery or productivity.</div><p>Recommended action: ask the employee to review the missing entry. In production, show sync timestamps and allow a reviewed reminder.</p><button class="button" data-dismiss="${id}">Mark reviewed in sample</button>`);}
function research(){show('Why this dashboard is different',`<p>The current manager template combines headcounts, monthly task counts and a team execution table. This concept adds explicit decisions and context.</p><h3>What competing products get right</h3><p><a href="https://help.asana.com/s/article/universal-reporting?language=en_US" target="_blank" rel="noopener">Asana reporting</a> connects task, project, portfolio and goal reporting. Adaptation: project pulse and measurable quarterly outcomes.</p><p><a href="https://support.monday.com/hc/en-us/articles/360010699760-The-Workload-Widget" target="_blank" rel="noopener">monday.com Workload</a> compares effort with work schedules and time off. Adaptation: planned hours divided by leave-adjusted capacity.</p><p><a href="https://help.clickup.com/hc/en-us/articles/25757497269143-Intro-to-cards" target="_blank" rel="noopener">ClickUp dashboard cards</a> support modular overviews. Adaptation: clickable summary cards and focused drill-downs.</p><h3>Recommended implementation order</h3><p><b>1. Make current data actionable:</b> scoped filters, overdue task links, incomplete effort checks, pending approvals, source freshness and clear formulas.</p><p><b>2. Add planning:</b> remaining task estimates, leave-adjusted capacity, blockers with owners and age, milestone and goal health.</p><p><b>3. Add follow-through:</b> audited task reassignment, coverage confirmation, saved views, weekly digest and delivery trend history.</p><h3>Metric definitions</h3><p>Overdue = open tasks with due date before the snapshot. Planned capacity = weekly assigned estimated effort / weekly available hours. Individual overload is surfaced even if total team load is below 100%. Logged effort uses elapsed capacity only. Goal examples track improvement from a baseline; production must expose baseline, current value and target.</p><p>Research checked 13 Oct 2026. All people, dates and metrics here are fictional. The briefing uses rules; it does not use AI or predict deadlines.</p>`);}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-project]');if(!b)return;if(b.id==='close')return $('#dialog').close();if(b.dataset.jump){$('#'+b.dataset.jump).scrollIntoView({behavior:'smooth'});return;}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('selected',x===b));render();return;}if(b.dataset.person)return person(+b.dataset.person);if(b.dataset.balance)return balance(+b.dataset.balance);if(b.dataset.project)return project(+b.dataset.project);if(b.dataset.alert)return alertDetail(+b.dataset.alert);if(b.id==='research'||b.id==='notes')return research();if(b.id==='reset'){state=structuredClone(seed);team='all';$('#team').value='all';$('#search').value='';filter='all';document.querySelectorAll('#tabs button').forEach(x=>x.classList.toggle('selected',x.dataset.filter==='all'));render();return toast('Sample data reset.');}if(b.dataset.unblock){state.projects.find(p=>p.id===+b.dataset.unblock).blocked=false;state.alerts=state.alerts.filter(a=>a.project!==+b.dataset.unblock);$('#dialog').close();render();return toast('Sample blocker resolved. Overdue tasks still need review.');}if(b.dataset.approve||b.dataset.decline||b.dataset.dismiss){const id=+(b.dataset.approve||b.dataset.decline||b.dataset.dismiss),a=state.alerts.find(a=>a.id===id);if(b.dataset.approve){state.people.find(p=>p.id===a.person).available=32;state.leaves.push({name:'Priya Nair',team:'Engineering',day:'16',backup:'Coverage not confirmed',state:'Approved'});state.alerts.push({id:6,type:'delivery',team:'Engineering',title:'Priya is 2h over capacity after approved leave',detail:'34h planned / 32h available · Confirm coverage or review scope',action:'Balance workload',person:2});}state.alerts=state.alerts.filter(a=>a.id!==id);$('#dialog').close();render();return toast('Updated sample only. No request or notification was sent.');}if(b.id==='export'){const rows=state.people.filter(inTeam);const csv=['Name,Team,Planned hours,Available hours,Open tasks,Overdue,Logged hours,Elapsed available hours,Goal percent',...rows.map(p=>[p.name,p.team,p.planned,p.available,p.open,p.overdue,p.logged??'',p.elapsed,p.goal].join(','))].join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='solulever-sample-team-12-16-oct.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sample team snapshot exported.');}});
document.addEventListener('submit',e=>{if(e.target.id!=='move-form')return;e.preventDefault();const f=new FormData(e.target),p=state.people.find(p=>p.id===+f.get('from')),q=state.people.find(p=>p.id===+f.get('owner'));p.planned-=4;q.planned+=4;p.open--;q.open++;const a=state.alerts.find(a=>a.person===p.id&&a.type==='delivery');if(a){if(p.planned<=p.available)state.alerts=state.alerts.filter(x=>x!==a);else{a.title=`${p.name.split(' ')[0]} has ${p.planned-p.available}h more work than capacity`;a.detail=`${p.planned}h planned / ${p.available}h available · Review remaining scope`;}}$('#dialog').close();render();toast('4h moved in the sample. Capacity and alerts recalculated.');});
$('#team').addEventListener('change',e=>{team=e.target.value;render();});$('#search').addEventListener('input',render);document.addEventListener('keydown',e=>{const p=e.target.closest('[data-project]');if(p&&(e.key==='Enter'||e.key===' ')){e.preventDefault();project(+p.dataset.project);}});render();
